const { evaluateThrottle, recordDelivery } = require('./throttling');

const DEFAULT_LOCALE = 'en-US';
const PREVIEW_LENGTH = 120;

/**
 * The per-channel strategy composed with the shared send pipeline.
 *
 * @typedef {object} ChannelDefinition
 * @property {string} channel Name used in payload ids, throttle keys and send results.
 * @property {object} defaults Channel settings; each resolves to `options[key] || defaults[key]`.
 * @property {(user: object) => void} validateUser Runs after the shared user checks; throws TypeError.
 * @property {Function[]} throttleRules Evaluated in order, see `evaluateThrottle`.
 * @property {(base: object, context: object) => object} format Returns fields merged over the base payload.
 * @property {(transport: object, payload: object) => Promise<void>} deliver
 */

/**
 * @param {ChannelDefinition} definition
 * @param {object} options Factory options shared by every channel plus the keys in `definition.defaults`.
 */
function createChannelNotifier(definition, options) {
  const notifier = {
    channel: definition.channel,
    transport: options.transport || {},
    throttleStore: options.throttleStore || new Map(),
    now: options.now || (() => new Date()),
    defaultLocale: options.defaultLocale || DEFAULT_LOCALE,
    ...resolveSettings(definition.defaults, options)
  };
  notifier.send = (user, message, sendOptions = {}) => send(notifier, definition, user, message, sendOptions);
  return notifier;
}

function resolveSettings(defaults, options) {
  return Object.fromEntries(
    Object.entries(defaults).map(([key, fallback]) => [key, options[key] || fallback])
  );
}

async function send(notifier, definition, user, message, options) {
  validateUser(user);
  definition.validateUser(user);
  validateMessage(message);

  const context = { notifier, user, message, options };
  const throttle = evaluateThrottle(definition.throttleRules, context);
  if (throttle.throttled) {
    return {
      channel: notifier.channel,
      status: 'throttled',
      reason: throttle.reason,
      retryAt: throttle.retryAt,
      userId: user.id
    };
  }

  const base = formatBase(context);
  const payload = { ...base, ...definition.format(base, context) };
  await definition.deliver(notifier.transport, payload);
  recordDelivery(context);

  return {
    channel: notifier.channel,
    status: 'sent',
    userId: user.id,
    id: payload.id,
    preview: payload.preview
  };
}

function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function formatBase({ notifier, user, message, options }) {
  const id = `${notifier.channel}-${user.id}-${notifier.now().getTime()}`;
  const locale = options.locale || user.locale || notifier.defaultLocale;
  const title = applyTemplate(message.title, user, message);
  const body = applyTemplate(message.body, user, message);

  return {
    id,
    channel: notifier.channel,
    locale,
    title,
    body,
    preview: `${title}: ${body}`.slice(0, PREVIEW_LENGTH),
    metadata: {
      category: message.category || 'general',
      priority: message.priority || 'normal',
      generatedAt: notifier.now().toISOString()
    }
  };
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

function deliverVia(transportKey, label = transportKey) {
  return async (transport, payload) => {
    if (typeof transport[transportKey] !== 'function') {
      throw new Error(`${label} transport is not configured`);
    }
    await transport[transportKey](payload);
  };
}

